<?php
header('Cache-Control: no-store, private');header('X-Content-Type-Options: nosniff');header('Content-Type: application/json; charset=utf-8');
function quoteContactFail($status,$message){http_response_code($status);echo json_encode(['error'=>$message],JSON_UNESCAPED_UNICODE);exit;}
try{
 session_start();if(empty($_SESSION['user'])||(isset($_SESSION['expire'])&&$_SESSION['expire']<time()))quoteContactFail(401,'Inicia sesión nuevamente.');
 require_once dirname(__DIR__).'/config/database.php';require_once __DIR__.'/ali-pos-security.php';require_once __DIR__.'/proforma-contact-core.php';$db=appPdoConnection();$access=aliPosCapabilities($db,$_SESSION['user']);if(empty($access['read']))quoteContactFail(403,'No tienes acceso a las proformas.');
 if(empty($_SESSION['proforma_contact_csrf']))$_SESSION['proforma_contact_csrf']=bin2hex(random_bytes(24));$csrf=$_SESSION['proforma_contact_csrf'];$method=$_SERVER['REQUEST_METHOD'];if(!in_array($method,['GET','POST'],true))quoteContactFail(405,'Método no permitido.');
 if($method==='POST'){if(empty($access['write']))quoteContactFail(403,'No tienes permiso para actualizar el teléfono.');if(!hash_equals($csrf,$_SERVER['HTTP_X_CONTACT_CSRF']??''))quoteContactFail(403,'Vuelve a cargar el teléfono e intenta nuevamente.');if((int)($_SERVER['CONTENT_LENGTH']??0)>4000)quoteContactFail(413,'Datos demasiado extensos.');$body=json_decode(file_get_contents('php://input'),true);if(!is_array($body))quoteContactFail(422,'Revisa los datos del teléfono.');$id=filter_var($body['IdCliente']??0,FILTER_VALIDATE_INT);}else{$id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT);}
 session_write_close();if(!$id||$id<1)quoteContactFail(422,'Selecciona un cliente.');
 if($method==='GET'){$s=$db->prepare('SELECT IdCliente,Cliente,Telefono FROM Ve_DocVentaCliente WHERE IdCliente=? AND COALESCE(Anulado,0)=0');$s->execute([$id]);$client=$s->fetch(PDO::FETCH_ASSOC);if(!$client)quoteContactFail(404,'Cliente no disponible.');$client['Telefono']=(string)$client['Telefono'];echo json_encode(['client'=>$client,'csrf'=>$csrf,'canWrite'=>!empty($access['write']),'valid'=>quotePhoneValid($client['Telefono'])],JSON_UNESCAPED_UNICODE);exit;}
 $db->beginTransaction();$client=quoteUpdateClientPhone($db,$id,$body['Telefono']??null,$body['anterior']??null);$db->commit();echo json_encode(['client'=>$client,'valid'=>true],JSON_UNESCAPED_UNICODE);
}catch(InvalidArgumentException $e){if(isset($db)&&$db->inTransaction())$db->rollBack();quoteContactFail(422,$e->getMessage());}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();if($e->getCode()===409)quoteContactFail(409,$e->getMessage());error_log('Proforma contact: '.$e->getMessage());quoteContactFail(500,'No se pudo guardar el teléfono. Tus datos se conservan.');}
